function l(r,f="YYYY-MM-DD HH:mm:ss"){if(!r)return"";const t=new Date(r);if(isNaN(t.getTime()))return r;const i=t.getFullYear(),a=String(t.getMonth()+1).padStart(2,"0"),n=String(t.getDate()).padStart(2,"0"),o=String(t.getHours()).padStart(2,"0"),e=String(t.getMinutes()).padStart(2,"0"),s=String(t.getSeconds()).padStart(2,"0");return f.replace("YYYY",i).replace("MM",a).replace("DD",n).replace("HH",o).replace("mm",e).replace("ss",s)}function u(r){if(!r)return"";const f=new Date,t=new Date(r),i=f-t,a=Math.floor(i/1e3),n=Math.floor(a/60),o=Math.floor(n/60),e=Math.floor(o/24),s=Math.floor(e/30),c=Math.floor(s/12);return a<60?"刚刚":n<60?`${n}分钟前`:o<24?`${o}小时前`:e<7?`${e}天前`:e<30?`${Math.floor(e/7)}周前`:s<12?`${s}个月前`:`${c}年前`}export{l as a,u as f};
